import React, { useState, useEffect, useMemo } from 'react';
import { Text, Billboard } from '@react-three/drei';
import * as THREE from 'three';

const TechCorner = ({ position, rotation, color = "#00ffcc" }) => (
  <group position={position} rotation={rotation}>
    {/* Horizontal line */}
    <mesh position={[10, 0, 0]}>
      <planeGeometry args={[20, 1.5]} />
      <meshBasicMaterial color={color} transparent opacity={0.8} depthWrite={false} />
    </mesh>
    {/* Vertical line */}
    <mesh position={[0, -10, 0]}>
      <planeGeometry args={[1.5, 20]} />
      <meshBasicMaterial color={color} transparent opacity={0.8} depthWrite={false} />
    </mesh>
  </group>
);

const WorldUI = ({ 
  position, 
  title, 
  description, 
  logoUrl, 
  titleColor = "#ffffff", 
  descColor = "#aaaaaa", 
  outlineColor = "#001133",
  scale = 1,
  visible = true
}) => {
  const [logoTex, setLogoTex] = useState(null);

  useEffect(() => {
    if (logoUrl) {
      const loader = new THREE.TextureLoader();
      loader.load(logoUrl, (tex) => {
        tex.colorSpace = THREE.SRGBColorSpace;
        setLogoTex(tex);
      });
    }
  }, [logoUrl]);

  // Derived theme color from title color
  const themeColor = useMemo(() => {
    return titleColor;
  }, [titleColor]);

  const halfWidth = 240;
  const halfHeight = 120;

  return (
    <group position={position} visible={visible}>
      <Billboard
        follow={true}
        lockX={false}
        lockY={false}
        lockZ={false}
      >
        <group scale={scale}>
          {/* Glass Backing Plate */}
          <mesh position={[0, 0, -5]}>
            <planeGeometry args={[halfWidth * 2, halfHeight * 2]} />
            <meshBasicMaterial 
              color="#010610" 
              opacity={0.8} 
              transparent 
              depthWrite={false} 
            />
          </mesh>

          {/* Holographic Glowing Inner Border */}
          <mesh position={[0, 0, -4.9]}>
            <planeGeometry args={[halfWidth * 2 - 8, halfHeight * 2 - 8]} />
            <meshBasicMaterial 
              color={themeColor} 
              opacity={0.03} 
              transparent 
              depthWrite={false} 
            />
          </mesh>

          {/* Technical Grid/Accent Lines */}
          <mesh position={[0, halfHeight - 12, -4]}>
            <planeGeometry args={[halfWidth * 2 - 30, 1]} />
            <meshBasicMaterial color={themeColor} opacity={0.25} transparent depthWrite={false} />
          </mesh>
          <mesh position={[0, -halfHeight + 12, -4]}>
            <planeGeometry args={[halfWidth * 2 - 30, 1]} />
            <meshBasicMaterial color={themeColor} opacity={0.25} transparent depthWrite={false} />
          </mesh>

          {/* Sci-Fi Corner Brackets */}
          <TechCorner position={[-halfWidth, halfHeight, -3]} rotation={[0, 0, 0]} color={themeColor} />
          <TechCorner position={[halfWidth, halfHeight, -3]} rotation={[0, 0, -Math.PI / 2]} color={themeColor} />
          <TechCorner position={[-halfWidth, -halfHeight, -3]} rotation={[0, 0, Math.PI / 2]} color={themeColor} />
          <TechCorner position={[halfWidth, -halfHeight, -3]} rotation={[0, 0, Math.PI]} color={themeColor} />

          {/* Tiny technical UI labels */}
          <Text
            font="/fonts/Roboto.woff"
            position={[-halfWidth + 15, halfHeight - 8, -3]}
            fontSize={6}
            color={themeColor}
            opacity={0.5}
            anchorX="left"
            anchorY="middle"
          >
            SYS.NODE_ID // 004A
          </Text>
          <Text
            font="/fonts/Roboto.woff"
            position={[halfWidth - 15, halfHeight - 8, -3]}
            fontSize={6}
            color={themeColor}
            opacity={0.5}
            anchorX="right"
            anchorY="middle"
          >
            STATUS: SECURE_LINK
          </Text>

          {logoTex && (
            <mesh position={[0, 40, 0]}>
              <planeGeometry args={[70, 70]} />
              <meshBasicMaterial 
                map={logoTex} 
                transparent 
                depthWrite={false} 
                blending={THREE.AdditiveBlending} 
              />
            </mesh>
          )}
          
          <Text 
            font="/fonts/Roboto.woff" 
            fallbackFonts={[]}
            position={[0, logoTex ? -15 : 15, 0]}
            fontSize={24}
            color={titleColor}
            outlineWidth={0.02}
            outlineColor={outlineColor}
            anchorX="center"
            anchorY="middle"
          >
            {title}
          </Text>
          
          {description && (
            <Text 
              font="/fonts/Roboto.woff" 
              fallbackFonts={[]}
              position={[0, logoTex ? -40 : -15, 0]}
              fontSize={11}
              color={descColor}
              outlineWidth={0.01}
              outlineColor={outlineColor}
              anchorX="center"
              anchorY="top"
              maxWidth={440}
              textAlign="center"
              lineHeight={1.4}
            >
              {description}
            </Text>
          )}
        </group>
      </Billboard>
    </group>
  );
};

export default WorldUI;
