const CheeringFans = () => {
  const fansRef = useRef();

  const { fans } = useMemo(() => {
    const fanList = [];
    let seed = 123;
    const rnd = () => {
      const x = Math.sin(seed++) * 10000;
      return x - Math.floor(x);
    };

    const leftXPositions = [-380, -420, -460, -500, -540];
    const rightXPositions = [380, 420, 460, 500, 540];

    const generateFansForSide = (xPositions, isRight) => {
      xPositions.forEach((x, rowIdx) => {
        const height = 40 + rowIdx * 50;
        const standY = -125 + height;
        // Place fans along Z from -460 to 460
        for (let z = -460; z <= 460; z += 32) {
          const fanX = x + (rnd() - 0.5) * 8;
          const fanZ = z + (rnd() - 0.5) * 8;
          const colors = ["#0088ff", "#00ffff", "#ff0044", "#ffffff", "#00ffaa"];
          const color = colors[Math.floor(rnd() * colors.length)];

          fanList.push({
            x: fanX,
            y: standY + 6,
            z: fanZ,
            color,
            offset: rnd() * Math.PI * 2
          });
        }
      });
    };

    generateFansForSide(leftXPositions, false);
    generateFansForSide(rightXPositions, true);

    return { fans: fanList };
  }, []);

  useFrame((state) => {
    if (!fansRef.current) return;

    const dummy = new THREE.Object3D();
    const tempColor = new THREE.Color();
    const t = (state.clock.elapsedTime) % 6; // 6s play loop
    const isCheering = t >= 4.0 || t < 0.5; // TD catch happens at t=4.0

    fans.forEach((f, idx) => {
      let jumpY = 0;
      let scaleY = 1.0;
      
      if (isCheering) {
        jumpY = Math.abs(Math.sin(state.clock.elapsedTime * 12 + f.offset)) * 14;
        scaleY = 1.0 + Math.sin(state.clock.elapsedTime * 24 + f.offset) * 0.15;
      } else {
        jumpY = Math.sin(state.clock.elapsedTime * 2 + f.offset) * 1.5;
      }

      dummy.position.set(f.x, f.y + jumpY, f.z);
      dummy.scale.set(3, 3 * scaleY, 3);
      dummy.updateMatrix();
      fansRef.current.setMatrixAt(idx, dummy.matrix);
      
      if (isCheering && Math.sin(state.clock.elapsedTime * 15 + f.offset) > 0.5) {
        tempColor.set("#ffffff");
      } else {
        tempColor.set(f.color);
      }
      fansRef.current.setColorAt(idx, tempColor);
    });

    fansRef.current.instanceMatrix.needsUpdate = true;
    if (fansRef.current.instanceColor) fansRef.current.instanceColor.needsUpdate = true;
  });

  return (
    <instancedMesh ref={fansRef} args={[null, null, fans.length]}>
      <capsuleGeometry args={[1, 3, 4, 8]} />
      <meshStandardMaterial roughness={0.5} metalness={0.1} />
    </instancedMesh>
  );
};

