import React, { useRef } from 'react';
import { Canvas, useFrame } from '@react-three/fiber';
import { Sparkles, ScrollControls, Scroll, useScroll, Html } from '@react-three/drei';
import { EffectComposer, Bloom, Noise, Vignette } from '@react-three/postprocessing';
import * as THREE from 'three';
import { CameraController, TimelineManager } from '../TimelineManager';
import GenerativeHUD from './GenerativeHUD';
import { easing } from 'maath';

// --- HTML Overlays (Intro Screen) ---
const HTMLStations = () => {
  const scroll = useScroll();
  const introRef = useRef();
  
  useFrame(() => {
    const progress = scroll.offset;
    if (introRef.current) {
      // Fade out smoothly within the first 3% of scroll
      const opacity = Math.max(0, 1 - progress / 0.03);
      introRef.current.style.opacity = opacity;
      introRef.current.style.transform = `translateY(${-progress * 300}px)`;
    }
  });

  return (
    <div style={{ position: 'absolute', top: 0, left: 0, width: '100vw', height: '100vh', pointerEvents: 'none' }}>
      {/* Intro Title */}
      <div 
        ref={introRef} 
        style={{ 
          position: 'absolute', 
          top: '38%', 
          left: '8%', 
          color: 'white', 
          opacity: 1, 
          transition: 'opacity 0.1s ease-out, transform 0.1s ease-out' 
        }}
      >
        <h1 className="text-8xl font-bold tracking-tighter bg-clip-text text-transparent bg-gradient-to-r from-cyan-400 via-teal-400 to-emerald-500 drop-shadow-[0_0_35px_rgba(6,182,212,0.4)]">
          Enter the Quantum Grid
        </h1>
        <p className="text-xl mt-6 text-cyan-400/80 font-mono tracking-[0.25em] drop-shadow-[0_0_10px_rgba(6,182,212,0.2)]">
          SCROLL DOWN TO INITIALIZE WARP SEQUENCE
        </p>
      </div>
    </div>
  );
};

// Dynamic Post-Processing Controller to swell bloom during high-velocity scrolls
const DynamicPostProcessing = () => {
  const scroll = useScroll();
  const bloomRef = useRef();

  useFrame((state, delta) => {
    if (bloomRef.current) {
      const velocity = Math.abs(scroll.delta) * 1000;
      // Swell bloom from baseline 1.2 up to max 5.5 during high-speed wraps
      const targetIntensity = 1.2 + Math.min(velocity * 0.45, 4.3);
      easing.damp(bloomRef.current, 'intensity', targetIntensity, 0.15, delta);
    }
  });

  return (
    <EffectComposer disableNormalPass>
      <Bloom 
        ref={bloomRef}
        luminanceThreshold={0.2} 
        intensity={1.2} 
      />
      <Noise opacity={0.02} />
      <Vignette eskil={false} offset={0.1} darkness={0.8} />
    </EffectComposer>
  );
};

const Scene3D = () => {
  return (
    <Canvas camera={{ fov: 75, near: 10, far: 8000 }} gl={{ antialias: false, alpha: true }}>
      {/* Background color removed for transparency */}
      
      <ScrollControls pages={10} damping={0.2} distance={1.2}>
        
        {/* The 3D World */}
        <React.Suspense fallback={null}>
          <CameraController />
          <TimelineManager />
        </React.Suspense>
        
        {/* The HTML UI Layer */}
        <Scroll html style={{ width: '100%', height: '100%', pointerEvents: 'none' }}>
          <HTMLStations />
        </Scroll>

        {/* Dynamic speed-reactive Post-Processing */}
        <DynamicPostProcessing />

      </ScrollControls>
    </Canvas>
  );
};

export default Scene3D;
