import React, { useRef, useMemo, useEffect } from 'react';
import { useFrame } from '@react-three/fiber';
import * as THREE from 'three';
import { useAsyncTexture } from '../../../hooks/useAsyncTexture';

// Volatility curve math (matches the camera path in TimelineManager.jsx)
const getWormholeCenterY = (localZ, length) => {
  const t = -localZ / length; // localZ is negative, so t goes 0 to 1
  if (t < 0 || t > 1) return 0;
  const fade = Math.sin(t * Math.PI);
  // Micro and macro volatility waves representing a real stock chart price trend
  const wave = Math.sin(t * Math.PI * 3.0) * 180 + Math.sin(t * Math.PI * 9.0) * 45;
  return wave * fade;
};

// Layout for "CQ" made of candlesticks
const getCQLayout = () => {
  const points = [];
  const addCandle = (x, y, color) => {
    points.push({ x, y, z: 0, rot: [Math.PI / 2, 0, 0], color, bodyHeight: 40 + Math.random() * 40 });
  };
  
  // "C" shape
  for (let a = Math.PI * 0.25; a < Math.PI * 1.75; a += 0.2) {
    addCandle( -100 + Math.cos(a) * 80, Math.sin(a) * 80, "#00ff00" );
  }
  
  // "Q" shape (O part)
  for (let a = 0; a < Math.PI * 2; a += 0.2) {
    addCandle( 100 + Math.cos(a) * 80, Math.sin(a) * 80, "#ff0044" );
  }
  // "Q" tail
  addCandle( 140, -40, "#ff0044" );
  addCandle( 160, -60, "#ff0044" );
  addCandle( 180, -80, "#ff0044" );
  
  return points;
};

const WormholeContango = ({ position, rotation = [0, 0, 0], length = 6000, radius = 250, visible }) => {
  const groupRef = useRef();
  const wickMeshRef = useRef();
  const bodyMeshRef = useRef();
  
  // Load the Contango image logo asynchronously
  const logoTexture = useAsyncTexture('/assets/images/contango_logo.png');

  // Compute all candlesticks data (tunnel + CQ logo)
  const allCandles = useMemo(() => {
    const items = [];
    const count = Math.floor(length / 5); 
    
    // 1. The Tunnel (Bending up/down along getWormholeCenterY)
    for (let i = 0; i < count; i++) {
      const z = -(i / count) * length;
      const t = i * 0.1;
      
      const yCenter = getWormholeCenterY(z, length);
      
      const x1 = Math.cos(t) * radius;
      const y1 = yCenter + Math.sin(t) * radius;
      
      const x2 = Math.cos(t + Math.PI) * radius;
      const y2 = yCenter + Math.sin(t + Math.PI) * radius;

      const isBull = Math.random() > 0.5;
      const color = isBull ? "#00ff00" : "#ff0044";
      const bodyHeight = 20 + Math.random() * 60;
      
      const rot1 = [0, 0, t + Math.PI / 2];
      const rot2 = [0, 0, t + Math.PI + Math.PI / 2];

      items.push({ x: x1, y: y1, z, rot: rot1, color, bodyHeight });
      items.push({ x: x2, y: y2, z, rot: rot2, color, bodyHeight });
    }
    
    // 2. The CQ Logo at the end of the tunnel (shifted vertically by logoY)
    const logoY = getWormholeCenterY(-length + 150, length);
    const cqLayout = getCQLayout();
    cqLayout.forEach(cq => {
      items.push({
        x: cq.x,
        y: cq.y + logoY,
        z: -length + 150,
        rot: cq.rot,
        color: cq.color,
        bodyHeight: cq.bodyHeight
      });
    });

    return items;
  }, [length, radius]);

  const totalCount = allCandles.length;

  useEffect(() => {
    if (!wickMeshRef.current || !bodyMeshRef.current) return;
    
    const tempObject = new THREE.Object3D();
    const tempColor = new THREE.Color();
    
    for (let i = 0; i < totalCount; i++) {
      const c = allCandles[i];
      
      // Position and Rotation
      tempObject.position.set(c.x, c.y, c.z);
      tempObject.rotation.set(c.rot[0], c.rot[1], c.rot[2]);
      
      // Wick Matrix
      tempObject.scale.set(1, c.bodyHeight + 40, 1);
      tempObject.updateMatrix();
      wickMeshRef.current.setMatrixAt(i, tempObject.matrix);
      tempColor.set(c.color);
      wickMeshRef.current.setColorAt(i, tempColor);
      
      // Body Matrix
      tempObject.scale.set(1, c.bodyHeight, 1);
      tempObject.updateMatrix();
      bodyMeshRef.current.setMatrixAt(i, tempObject.matrix);
      bodyMeshRef.current.setColorAt(i, tempColor);
    }
    
    wickMeshRef.current.instanceMatrix.needsUpdate = true;
    if (wickMeshRef.current.instanceColor) wickMeshRef.current.instanceColor.needsUpdate = true;
    
    bodyMeshRef.current.instanceMatrix.needsUpdate = true;
    if (bodyMeshRef.current.instanceColor) bodyMeshRef.current.instanceColor.needsUpdate = true;
  }, [allCandles, totalCount]);

  useFrame((state) => {
    if (groupRef.current && visible) {
      groupRef.current.rotation.z = state.clock.elapsedTime * 0.3;
    }
  });

  // Calculate logo vertical offset
  const logoY = useMemo(() => getWormholeCenterY(-length + 150, length), [length]);

  // Generate curved central glow segments
  const glowSegments = useMemo(() => {
    const segs = [];
    const count = 15;
    const segLength = length / count;
    for (let j = 0; j < count; j++) {
      const z = -(j / count) * length - (segLength / 2);
      const y = getWormholeCenterY(z, length);
      segs.push({ y, z });
    }
    return segs;
  }, [length]);

  // Generate glowing neon stock-chart trendline
  const trendlineSegments = useMemo(() => {
    const segs = [];
    const count = 60;
    
    for (let j = 0; j < count; j++) {
      const z1 = -(j / count) * length;
      const z2 = -((j + 1) / count) * length;
      const y1 = getWormholeCenterY(z1, length);
      const y2 = getWormholeCenterY(z2, length);
      
      const posX = 0;
      const posY = (y1 + y2) / 2;
      const posZ = (z1 + z2) / 2;
      
      const dy = y2 - y1;
      const dz = z2 - z1;
      const dist = Math.sqrt(dy * dy + dz * dz);
      
      const dir = new THREE.Vector3(0, dy, dz).normalize();
      const quat = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 0, -1), dir);
      
      // Neon Green if price goes up, Neon Red if price goes down as camera flies forward (decreasing Z)
      const color = y2 > y1 ? "#00ff88" : "#ff0055";
      
      segs.push({ x: posX, y: posY, z: posZ, len: dist, quat, color });
    }
    return segs;
  }, [length]);

  return (
    <group position={position} rotation={rotation} visible={visible}>
      {/* Candlestick Tunnel mesh */}
      <group ref={groupRef}>
        <instancedMesh ref={wickMeshRef} args={[null, null, totalCount]}>
          <cylinderGeometry args={[2, 2, 1, 8]} />
          <meshStandardMaterial roughness={0.4} emissiveIntensity={0.2} />
        </instancedMesh>
        
        <instancedMesh ref={bodyMeshRef} args={[null, null, totalCount]}>
          <boxGeometry args={[10, 1, 10]} />
          <meshStandardMaterial roughness={0.4} emissiveIntensity={0.8} />
        </instancedMesh>
      </group>
      
      {/* 2D Image texture floating in the middle of CQ */}
      <mesh position={[0, logoY, -length + 150]}>
        <planeGeometry args={[200, 200]} />
        <meshBasicMaterial map={logoTexture} transparent={true} />
      </mesh>
      
      {/* Central glow segments following the curve */}
      {glowSegments.map((seg, idx) => (
        <mesh key={idx} position={[0, seg.y, seg.z]} rotation={[Math.PI / 2, 0, 0]}>
          <cylinderGeometry args={[radius * 0.8, radius * 0.8, length / 15, 16, 1, true]} />
          <meshBasicMaterial color="#00ff00" transparent opacity={0.03} side={THREE.BackSide} />
        </mesh>
      ))}

      {/* Glowing neon trendline tracing the volatility curve */}
      {trendlineSegments.map((seg, idx) => {
        const rotationEuler = new THREE.Euler().setFromQuaternion(seg.quat);
        return (
          <mesh 
            key={idx} 
            position={[seg.x, seg.y, seg.z]} 
            rotation={[rotationEuler.x, rotationEuler.y, rotationEuler.z]}
          >
            <boxGeometry args={[4, 4, seg.len]} />
            <meshBasicMaterial color={seg.color} toneMapped={false} />
          </mesh>
        );
      })}
    </group>
  );
};

export default WormholeContango;
