import React, { useState, useRef, useEffect } from 'react';
import { hudStore } from './GenerativeHUD';

export const VoiceAgentSystem = ({ position = [0, 0, 0] }) => {
  const [isListening, setIsListening] = useState(false);
  
  const recognition = useRef(null);
  const audioContext = useRef(null);
  const analyser = useRef(null);
  const dataArray = useRef(null);
  const animationFrame = useRef(null);
  const localStream = useRef(null);
  const buttonRef = useRef(null);
  const canvasRef = useRef(null);

  useEffect(() => {
    const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
    if (SpeechRecognition) {
      recognition.current = new SpeechRecognition();
      recognition.current.continuous = true;
      recognition.current.interimResults = true;
      
      recognition.current.onresult = (event) => {
        let interimTranscript = '';
        let finalTranscript = '';
        
        for (let i = event.resultIndex; i < event.results.length; ++i) {
          if (event.results[i].isFinal) {
            finalTranscript += event.results[i][0].transcript;
          } else {
            interimTranscript += event.results[i][0].transcript;
          }
        }
        
        if (finalTranscript) {
          hudStore.pushMessage(`User: ${finalTranscript}`, 'user_voice');
          
          if (finalTranscript.toLowerCase().includes('generate')) {
            hudStore.pushMessage("Agent: Dispatching Generative UI request...", 'agent');
            fetch('http://localhost:3001/api/generative-ui', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ query: finalTranscript })
            })
              .then(res => res.json())
              .then(data => {
                hudStore.pushMessage("Agent: Dynamic layout constructed.", 'agent');
                hudStore.setComponent(
                  <div className="bg-black/95 border border-cyan-400 p-8 rounded-2xl backdrop-blur-md shadow-[0_0_40px_rgba(0,255,255,0.3)] text-white font-mono max-w-sm relative pointer-events-auto">
                    {/* Sci-Fi Brackets */}
                    <div className="absolute top-0 left-0 w-3 h-3 border-t-2 border-l-2 border-cyan-400" />
                    <div className="absolute top-0 right-0 w-3 h-3 border-t-2 border-r-2 border-cyan-400" />
                    <div className="absolute bottom-0 left-0 w-3 h-3 border-b-2 border-l-2 border-cyan-400" />
                    <div className="absolute bottom-0 right-0 w-3 h-3 border-b-2 border-r-2 border-cyan-400" />
                    
                    <h3 className="text-xl font-bold mb-2 tracking-wider text-cyan-400 uppercase">COGNITIVE BOARD</h3>
                    <p className="text-[10px] text-gray-500 mb-6 uppercase">Source: "{finalTranscript}"</p>
                    <div className="grid grid-cols-2 gap-4">
                      {data.data.charts.map((c, i) => (
                        <div key={i} className="bg-cyan-950/20 border border-cyan-500/20 p-4 rounded text-center">
                          <div className="text-3xl font-extrabold text-cyan-300">{c.value}%</div>
                          <div className="text-[9px] text-cyan-400/80 uppercase mt-1 tracking-wider">{c.title}</div>
                        </div>
                      ))}
                    </div>
                  </div>
                );
              })
              .catch(err => {
                console.warn('[VoiceAgentSystem] Generative UI offline, using simulation response.');
                hudStore.pushMessage("Agent: Dynamic layout constructed (Simulation).", 'agent');
                hudStore.setComponent(
                  <div className="bg-black/95 border border-cyan-400 p-8 rounded-2xl backdrop-blur-md shadow-[0_0_40px_rgba(0,255,255,0.3)] text-white font-mono max-w-sm relative pointer-events-auto">
                    {/* Sci-Fi Brackets */}
                    <div className="absolute top-0 left-0 w-3 h-3 border-t-2 border-l-2 border-cyan-400" />
                    <div className="absolute top-0 right-0 w-3 h-3 border-t-2 border-r-2 border-cyan-400" />
                    <div className="absolute bottom-0 left-0 w-3 h-3 border-b-2 border-l-2 border-cyan-400" />
                    <div className="absolute bottom-0 right-0 w-3 h-3 border-b-2 border-r-2 border-cyan-400" />
                    
                    <h3 className="text-xl font-bold mb-2 tracking-wider text-cyan-400 uppercase">COGNITIVE BOARD</h3>
                    <p className="text-[10px] text-gray-500 mb-6 uppercase">Source: "{finalTranscript}"</p>
                    <div className="grid grid-cols-2 gap-4">
                      <div className="bg-cyan-950/20 border border-cyan-500/20 p-4 rounded text-center">
                        <div className="text-3xl font-extrabold text-cyan-300">85%</div>
                        <div className="text-[9px] text-cyan-400/80 uppercase mt-1 tracking-wider">User Engagement</div>
                      </div>
                      <div className="bg-cyan-950/20 border border-cyan-500/20 p-4 rounded text-center">
                        <div className="text-3xl font-extrabold text-cyan-300">92%</div>
                        <div className="text-[9px] text-cyan-400/80 uppercase mt-1 tracking-wider">Agent Efficiency</div>
                      </div>
                    </div>
                  </div>
                );
              });
          } else {
            // General query proxies to Voicebox mock backend
            fetch('http://localhost:3001/api/voice', {
              method: 'POST',
              headers: { 'Content-Type': 'application/json' },
              body: JSON.stringify({ text: finalTranscript })
            })
              .then(res => res.json())
              .then(data => {
                hudStore.pushMessage(`Agent: ${data.text}`, 'agent');
              })
              .catch(err => {
                console.warn('[VoiceAgentSystem] Voice interop offline, using local simulator.');
                hudStore.pushMessage(`Agent: Processing voice stream chunk... "${finalTranscript}"`, 'agent');
              });
          }
        }
      };

      recognition.current.onerror = (event) => {
        console.warn("Speech recognition error", event.error);
        if (event.error === 'not-allowed') {
          stopListening();
        }
      };
      
      recognition.current.onend = () => {
        if (isListening) {
          try {
            recognition.current.start();
          } catch (e) {
            console.warn("Failed to restart recognition", e);
          }
        }
      };
    }

    return () => {
      stopListening();
    };
  }, [isListening]);

  const startListening = async () => {
    try {
      const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
      localStream.current = stream;
      setIsListening(true);
      
      if (recognition.current) {
        try {
          recognition.current.start();
        } catch(e) { /* already started */ }
      }
      
      hudStore.pushMessage("Voice Agent Activated. Always-on voice listening.", 'system');

      audioContext.current = new (window.AudioContext || window.webkitAudioContext)();
      const source = audioContext.current.createMediaStreamSource(stream);
      analyser.current = audioContext.current.createAnalyser();
      analyser.current.fftSize = 256;
      source.connect(analyser.current);
      
      const bufferLength = analyser.current.frequencyBinCount;
      dataArray.current = new Uint8Array(bufferLength);
      
      updateAudioLevel();
    } catch (err) {
      console.warn("Microphone access denied or failed", err);
      hudStore.pushMessage("Microphone access denied.", 'error');
    }
  };

  const stopListening = () => {
    setIsListening(false);
    
    if (recognition.current) {
      try {
        recognition.current.stop();
      } catch (e) {}
    }

    if (localStream.current) {
      localStream.current.getTracks().forEach(track => track.stop());
      localStream.current = null;
    }

    if (audioContext.current && audioContext.current.state !== 'closed') {
      audioContext.current.close();
    }
    
    if (animationFrame.current) {
      cancelAnimationFrame(animationFrame.current);
    }
    
    hudStore.pushMessage("Voice Agent Deactivated. Defaulting to mouse movement tracking.", 'system');
  };

  const updateAudioLevel = () => {
    if (!analyser.current || !dataArray.current) return;
    
    analyser.current.getByteFrequencyData(dataArray.current);
    const len = dataArray.current.length;

    // Draw circular waveform onto overlay canvas
    if (canvasRef.current) {
      const canvas = canvasRef.current;
      const ctx = canvas.getContext('2d');
      const w = canvas.width;
      const h = canvas.height;
      
      ctx.clearRect(0, 0, w, h);
      
      const centerX = w / 2;
      const centerY = h / 2;
      const baseRadius = 38; // Matches outer boundary of button

      // Layer 1: Glowing Fuchsia Core Wave
      ctx.beginPath();
      for (let i = 0; i < len; i++) {
        const angle = (i / len) * Math.PI * 2;
        const val = dataArray.current[i] / 255.0;
        const r = baseRadius + val * 45; // amplitude offset
        const x = centerX + Math.cos(angle) * r;
        const y = centerY + Math.sin(angle) * r;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.strokeStyle = 'rgba(217, 70, 239, 0.7)'; // Fuchsia
      ctx.lineWidth = 2;
      ctx.shadowBlur = 12;
      ctx.shadowColor = '#d946ef';
      ctx.stroke();

      // Layer 2: Inner Cyan Harmonic Wave (shifted PI/4)
      ctx.beginPath();
      for (let i = 0; i < len; i++) {
        const angle = (i / len) * Math.PI * 2 + Math.PI / 4;
        const val = dataArray.current[len - 1 - i] / 255.0;
        const r = baseRadius + val * 25;
        const x = centerX + Math.cos(angle) * r;
        const y = centerY + Math.sin(angle) * r;
        if (i === 0) ctx.moveTo(x, y);
        else ctx.lineTo(x, y);
      }
      ctx.closePath();
      ctx.strokeStyle = 'rgba(6, 182, 212, 0.5)'; // Cyan
      ctx.lineWidth = 1;
      ctx.shadowBlur = 6;
      ctx.shadowColor = '#06b6d4';
      ctx.stroke();
    }

    // Dynamic scale scaling for the center orb
    let sum = 0;
    for (let i = 0; i < len; i++) {
      sum += dataArray.current[i];
    }
    const average = sum / len;
    if (buttonRef.current) {
      buttonRef.current.style.transform = `scale(${1 + (average / 180)})`;
    }
    
    animationFrame.current = requestAnimationFrame(updateAudioLevel);
  };

  return (
    <div className="flex flex-col items-center select-none">
      <div className="relative flex items-center justify-center w-40 h-40">
        
        {/* Real-time Visualizer Canvas */}
        {isListening && (
          <canvas
            ref={canvasRef}
            width={160}
            height={160}
            className="absolute inset-0 pointer-events-none z-0"
          />
        )}

        {/* Glowing Pulsing AI Core Button */}
        <button
          ref={buttonRef}
          onClick={isListening ? stopListening : startListening}
          title={isListening ? "Disable Always-on Voice" : "Enable Always-on Voice"}
          className={`w-18 h-18 rounded-full flex items-center justify-center transition-all duration-300 backdrop-blur-md border pointer-events-auto cursor-pointer z-10 ${
            isListening 
              ? 'bg-fuchsia-600/30 border-fuchsia-400 shadow-[0_0_35px_rgba(217,70,239,0.8)]' 
              : 'bg-white/5 border-white/20 hover:bg-white/10 hover:border-cyan-400/40 hover:shadow-[0_0_20px_rgba(6,182,212,0.3)]'
          }`}
          style={{
            transform: `scale(1)`,
          }}
        >
          <svg xmlns="http://www.w3.org/2000/svg" className={`h-8 w-8 ${isListening ? 'text-white' : 'text-cyan-400'}`} fill="none" viewBox="0 0 24 24" stroke="currentColor">
            {isListening ? (
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
            ) : (
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 11a7 7 0 01-7 7m0 0a7 7 0 01-7-7m7 7v4m0 0H8m4 0h4m-4-8a3 3 0 01-3-3V5a3 3 0 116 0v6a3 3 0 01-3 3z" />
            )}
          </svg>
        </button>
      </div>
      
      {isListening && (
        <div className="text-fuchsia-400 font-mono text-xs tracking-widest animate-pulse pointer-events-none text-center">
          VOICE AGENT ACTIVE<br/>
          <span className="text-[10px] text-fuchsia-400/70">Say "Generate a dashboard"</span>
        </div>
      )}
      {!isListening && (
        <div className="text-cyan-400/60 font-mono text-[10px] tracking-widest pointer-events-none text-center">
          MOUSE TRACKING ACTIVE
        </div>
      )}
    </div>
  );
};

export default VoiceAgentSystem;
