import React, { useRef } from 'react';
import { useScroll } from '@react-three/drei';
import { useFrame } from '@react-three/fiber';

export const IsolatedLights = ({ start, end, children }) => {
  const scroll = useScroll();
  const groupRef = useRef();
  const baseIntensities = useRef([]);

  useFrame((state, delta) => {
    if (!groupRef.current) return;
    const p = scroll.offset;

    // Calculate fade factor
    let fade = 0;
    if (p >= start && p <= end) {
      const center = (start + end) / 2;
      const halfRange = (end - start) / 2;
      const dist = Math.abs(p - center);
      fade = 1.0 - dist / halfRange;
      // Apply smooth transition curve
      fade = fade * fade * (3.0 - 2.0 * fade);
    }

    // Traverse group and multiply light intensities
    let index = 0;
    groupRef.current.traverse((node) => {
      if (node.isLight) {
        // Cache base intensity on first run
        if (baseIntensities.current[index] === undefined) {
          baseIntensities.current[index] = node.intensity;
        }
        node.intensity = baseIntensities.current[index] * fade;
        index++;
      }
    });
  });

  return <group ref={groupRef}>{children}</group>;
};

export default IsolatedLights;
