// --- CANDLESTICK CORRIDOR MAZE ---
// Volatile maze path generator function (local copy matching TimelineManager)
const getVolatilityPath = (z) => {
  if (z > -18500) return { x: 0, y: -11750 };
  if (z < -24200) return { x: 0, y: -11750 };

  const startZ = -18500;
  const stopZ = -24200;
  const t = (z - startZ) / (stopZ - startZ); // 0 to 1
  const fade = Math.sin(t * Math.PI); // smooth dampening at ends

  // Barclays Agg daily bond style (gentle, low-variance daily waves)
  const y = -11750 + Math.sin(t * Math.PI * 4.0) * 65 * fade;

  return { x: 0, y };
};

// --- CANDLESTICK CORRIDOR MAZE (INSTANCED FOR MAXIMUM PERFORMANCE) ---
const CandleMaze = () => {
  const bodyRef = useRef();
  const wickRef = useRef();
  const emaRef = useRef();

  const { candles, emaDots } = useMemo(() => {
    const list = [];
    const dots = [];
    const seedRandom = (s) => {
      const x = Math.sin(s) * 10000;
      return x - Math.floor(x);
    };

    let seed = 42;
    // Generate corridor matching camera path from local Z = 6250 down to Z = 600
    for (let z = 6250; z >= 600; z -= 75) {
      const worldZ = z - 24800;
      const pathVal = getVolatilityPath(worldZ);
      const centerX = pathVal.x;
      const centerY = pathVal.y - (-11750); // relative to world Y (-11750)

      // Helper to generate a candle config
      const makeCandle = (x, y) => {
        const isBullish = seedRandom(seed++) > 0.48;
        const color = isBullish ? '#00ff88' : '#ff0055';
        const bodyH = seedRandom(seed++) * 80 + 40; // low variance height
        const wickH = bodyH + seedRandom(seed++) * 50 + 20;

        return {
          x,
          y,
          z,
          w: 12,
          h: bodyH,
          d: 12,
          wickH,
          color,
          isWick: true
        };
      };

      // 4-sided cage corridor
      // Left wall candle
      list.push(makeCandle(centerX - 130, centerY + Math.sin(z * 0.008) * 30));
      // Right wall candle
      list.push(makeCandle(centerX + 130, centerY + Math.cos(z * 0.008) * 30));
      // Floor candle (bottom row)
      list.push(makeCandle(centerX + Math.sin(z * 0.01) * 60, centerY - 100));
      // Ceiling candle (top row)
      list.push(makeCandle(centerX + Math.cos(z * 0.01) * 60, centerY + 180));

      // Price grid horizontal line at intervals
      if (z % 250 === 0) {
        const lineY = centerY + (seedRandom(seed++) > 0.5 ? 40 : -40);
        list.push({
          x: centerX,
          y: lineY,
          z,
          w: 260,
          h: 1,
          d: 1,
          wickH: 0,
          color: '#ffffff',
          opacity: 0.12,
          isWick: false
        });
      }
    }

    // Generate EMA dots flanking the camera (aligned to smooth bond waves)
    for (let z = 6250; z >= 600; z -= 35) {
      const worldZ = z - 24800;
      const pathVal = getVolatilityPath(worldZ);
      const centerX = pathVal.x;
      const centerY = pathVal.y - (-11750);

      const leftY = centerY - 30 + Math.sin(z * 0.015) * 20;
      const rightY = centerY - 30 + Math.cos(z * 0.015) * 20;

      dots.push({ x: centerX - 35, y: leftY, z, color: '#00ffff' });
      dots.push({ x: centerX + 35, y: rightY, z, color: '#ff00ff' });
    }

    return { candles: list, emaDots: dots };
  }, []);

  const totalCandles = candles.length;
  const totalDots = emaDots.length;

  React.useEffect(() => {
    if (!bodyRef.current || !wickRef.current || !emaRef.current) return;

    const dummy = new THREE.Object3D();
    const tempColor = new THREE.Color();

    // Setup candles
    candles.forEach((c, idx) => {
      // Body
      dummy.position.set(c.x, c.y, c.z);
      dummy.scale.set(c.w, c.h, c.d);
      dummy.updateMatrix();
      bodyRef.current.setMatrixAt(idx, dummy.matrix);

      // Wick (TradingView-style wick running all the way through the body)
      if (c.isWick) {
        dummy.position.set(c.x, c.y, c.z);
        dummy.scale.set(2, c.wickH, 2);
      } else {
        // Horizontal grid bars
        dummy.position.set(0, 0, 0);
        dummy.scale.set(0, 0, 0);
      }
      dummy.updateMatrix();
      wickRef.current.setMatrixAt(idx, dummy.matrix);

      tempColor.set(c.color);
      bodyRef.current.setColorAt(idx, tempColor);
      wickRef.current.setColorAt(idx, tempColor);
    });

    // Setup EMA Dots
    emaDots.forEach((d, idx) => {
      dummy.position.set(d.x, d.y, d.z);
      dummy.scale.set(4, 4, 4);
      dummy.updateMatrix();
      emaRef.current.setMatrixAt(idx, dummy.matrix);

      tempColor.set(d.color);
      emaRef.current.setColorAt(idx, tempColor);
    });

    bodyRef.current.instanceMatrix.needsUpdate = true;
    if (bodyRef.current.instanceColor) bodyRef.current.instanceColor.needsUpdate = true;
    wickRef.current.instanceMatrix.needsUpdate = true;
    if (wickRef.current.instanceColor) wickRef.current.instanceColor.needsUpdate = true;
    emaRef.current.instanceMatrix.needsUpdate = true;
    if (emaRef.current.instanceColor) emaRef.current.instanceColor.needsUpdate = true;
  }, [candles, emaDots]);

  return (
    <group>
      {/* Candle Bodies */}
      <instancedMesh ref={bodyRef} args={[null, null, totalCandles]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshBasicMaterial toneMapped={false} />
      </instancedMesh>

      {/* Candle Wicks */}
      <instancedMesh ref={wickRef} args={[null, null, totalCandles]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshBasicMaterial toneMapped={false} />
      </instancedMesh>

      {/* Dotted EMA indicator lines */}
      <instancedMesh ref={emaRef} args={[null, null, totalDots]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshBasicMaterial toneMapped={false} />
      </instancedMesh>
    </group>
  );
};

