// --- INSTANCED SAFE DEPOSIT BOXES ON WALLS ---
const SafeDepositBoxes = () => {
  const boxRef = useRef();
  const dialRef = useRef();

  const { boxes, dials } = useMemo(() => {
    const boxList = [];
    const dialList = [];
    
    let seed = 77;
    const rnd = () => {
      const x = Math.sin(seed++) * 10000;
      return x - Math.floor(x);
    };

    // Columns along Z (from -1200 to 2250, steps of 95)
    // Rows along Y (from -180 to 600, steps of 45)
    const generateWall = (xPos, isRightWall) => {
      for (let z = -1200; z <= 2250; z += 95) {
        for (let y = -180; y <= 600; y += 45) {
          // Skip if inside the vault door entry tunnel area
          if (z < -1000 && Math.abs(y - 300) < 150) continue;

          // Highly reflective silver stainless steel tones
          const baseColor = rnd() > 0.6 ? "#f3f4f6" : rnd() > 0.3 ? "#e5e7eb" : "#d1d5db";

          boxList.push({
            x: xPos,
            y,
            z,
            ry: isRightWall ? -Math.PI / 2 : Math.PI / 2,
            color: baseColor
          });

          // Gold combo dial locks offset on door face
          const lockOffsetZ = (isRightWall ? -1 : 1) * 20;
          dialList.push({
            x: xPos + (isRightWall ? -5.5 : 5.5),
            y,
            z: z + lockOffsetZ,
            ry: isRightWall ? -Math.PI / 2 : Math.PI / 2
          });
        }
      }
    };

    generateWall(-220, false);
    generateWall(220, true);

    return { boxes: boxList, dials: dialList };
  }, []);

  useEffect(() => {
    if (!boxRef.current || !dialRef.current) return;

    const dummy = new THREE.Object3D();
    const tempColor = new THREE.Color();

    // Setup Doors
    boxes.forEach((b, idx) => {
      dummy.position.set(b.x, b.y, b.z);
      dummy.rotation.set(0, b.ry, 0);
      dummy.scale.set(80, 36, 10);
      dummy.updateMatrix();
      boxRef.current.setMatrixAt(idx, dummy.matrix);
      tempColor.set(b.color);
      boxRef.current.setColorAt(idx, tempColor);
    });

    // Setup Dial Wheels (Cylinders)
    dials.forEach((d, idx) => {
      dummy.position.set(d.x, d.y, d.z);
      dummy.rotation.set(Math.PI / 2, d.ry, 0);
      dummy.scale.set(6, 4, 6);
      dummy.updateMatrix();
      dialRef.current.setMatrixAt(idx, dummy.matrix);
    });

    boxRef.current.instanceMatrix.needsUpdate = true;
    if (boxRef.current.instanceColor) boxRef.current.instanceColor.needsUpdate = true;
    dialRef.current.instanceMatrix.needsUpdate = true;
  }, [boxes, dials]);

  return (
    <group>
      {/* Polished Silver Doors */}
      <instancedMesh ref={boxRef} args={[null, null, boxes.length]}>
        <boxGeometry args={[1, 1, 1]} />
        <meshStandardMaterial metalness={1.0} roughness={0.12} toneMapped={false} />
      </instancedMesh>

      {/* Polished Gold Dial Combination Locks */}
      <instancedMesh ref={dialRef} args={[null, null, dials.length]}>
        <cylinderGeometry args={[1, 1, 1, 12]} />
        <meshStandardMaterial color="#d4af37" metalness={1.0} roughness={0.05} />
      </instancedMesh>
    </group>
  );
};

