// --- MAIN COMPONENT ---
const ContangoQuant = ({ position, rotation, visible }) => {
  const scroll = useScroll();
  const lockRef = useRef({ triggered: false, timer: 0, locked: false });

  useFrame((state, delta) => {
    if (!visible) return;
    const p = scroll.offset;
    const s = lockRef.current;
    
    if (!s.triggered && p >= 0.92) {
      s.triggered = true;
      s.locked = true;
      if (scroll.el) {
        scroll.el.style.overflow = 'hidden';
        scroll.el.scrollTop = 0.93 * (scroll.el.scrollHeight - scroll.el.clientHeight);
      }
    }
    
    if (s.locked) {
      s.timer += delta;
      if (s.timer > 2.0) {
        s.locked = false;
        if (scroll.el) scroll.el.style.overflow = 'auto';
      } else {
        if (scroll.el) scroll.el.scrollTop = 0.93 * (scroll.el.scrollHeight - scroll.el.clientHeight);
      }
    }
  });

  return (
    <group visible={visible} position={position} rotation={rotation}>
      <IsolatedLights start={0.89} end={0.96}>
        <ambientLight intensity={1.5} color="#ffffff" />
        <directionalLight position={[0, 1000, 0]} intensity={2.0} color="#ffffff" />
        <pointLight position={[0, 300, 250]} intensity={20.0} color="#ffaa00" distance={1200} />
        <pointLight position={[0, 300, -250]} intensity={18.0} color="#00e1ff" distance={1200} />
        <pointLight position={[0, 400, 750]} intensity={15.0} color="#ffffff" distance={1000} />
      </IsolatedLights>
      
      {/* Futuristic Vault Environment (Floor and Vault Door) */}
      <VaultEnvironment />
      
      {/* Golden Treasury Stack & Diamonds */}
      <VaultTreasury />

      {/* Info Plaza Spot at Local Z = 150 (Camera stops at Z = 600) */}
      <WorldUI 
        position={[0, 80, 150]}
        title="CONTANGO QUANT"
        description="THE PHYSICS OF FINANCE // OPTIONS & SWARM EXECUTION

Automated options modeling, delta hedging, and spread execution. Contango Quant maps structural volatility, routing quantitative algorithms directly to dark pools to harvest liquidity imbalances."
        logoUrl="/contango_quant_logo.png"
        outlineColor="#271800"
        titleColor="#ffaa00"
        descColor="#ffcc66"
        scale={1.2}
      />

      {visible && (
        <AvatarSystem 
          position={[0, -100, 280]} 
          scale={2.2} 
          greeting="Welcome to Contango Quant. The market maze has been traversed." 
        />
      )}
    </group>
  );
};

