// Volatile stock chart price wave: camera goes up and down inside the wormhole
export const getVolatilityPath = (z) => {
  const startZ = -18500;
  const stopZ = -22550; // The end of the wormhole

  if (z > startZ) return { x: 0, y: -11750, rx: 0, ry: 0 };
  if (z < stopZ) return { x: 0, y: -11750, rx: 0, ry: 0 };

  const t = (z - startZ) / (stopZ - startZ); // 0 to 1
  const fade = Math.sin(t * Math.PI); // smooth dampening at ends

  // Macro trend wave + noisy micro fluctuations representing real volatility
  const wave = Math.sin(t * Math.PI * 3.0) * 180 + Math.sin(t * Math.PI * 9.0) * 45;
  const y = -11750 + wave * fade;

  // Pitch rx based on derivative: dy_dz = (dy_dt) * (dt_dz)
  const dy_dt = (3.0 * Math.PI * Math.cos(t * Math.PI * 3.0) * 180 + 9.0 * Math.PI * Math.cos(t * Math.PI * 9.0) * 45) * fade 
                + wave * Math.PI * Math.cos(t * Math.PI);
  const dy_dz = dy_dt / (stopZ - startZ);
  const rx = -Math.atan(dy_dz);

  return { x: 0, y, rx, ry: 0 };
};

const contangoKeyframes = [];
const steps = 40;
for (let i = 0; i <= steps; i++) {
  const t = i / steps;
  const p = 0.88 + t * 0.03; // progress from 0.88 to 0.91
  const z = -18500 + t * (-24200 - (-18500)); // Goes to the vault pause spot Z = -24200
  const pathVal = getVolatilityPath(z);
  contangoKeyframes.push({
    p,
    x: pathVal.x,
    y: pathVal.y,
    z,
    rx: pathVal.rx,
    ry: pathVal.ry
  });
}

